export class RtPipelineDesc {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    // Ray tracing pipelines of any shape: a description built with the Donut_RtPipeline* functions,
    // freed by Donut_CreateRayTracingPipelineFromDesc. maxRecursionDepth 1 = no rays from hit shaders.
    static create(maxPayloadSize: int, maxRecursionDepth: int): RtPipelineDesc {
        return new RtPipelineDesc(Donut_CreateRayTracingPipelineDesc(maxPayloadSize, maxRecursionDepth));
    }

    addGlobalBindingLayout(bindingLayout: Opaque): void {
        Donut_RtPipelineAddGlobalBindingLayout(this.handle, bindingLayout);
    }

    // A ray generation or miss shader, exported by its entry name.
    addShader(shaderLibrary: Opaque, entryName: string, shaderType: ShaderType): void {
        Donut_RtPipelineAddShader(this.handle, shaderLibrary, entryName, shaderType);
    }

    // Triangle hit group; "" for no closest-hit / any-hit shader; an optional local binding layout
    // (D3D12 only), whose binding sets come with each shader table entry.
    addHitGroup(shaderLibrary: Opaque, exportName: string, closestHitEntry: string, anyHitEntry: string, localBindingLayout: Opaque | null): void {
        Donut_RtPipelineAddHitGroup(this.handle, shaderLibrary, exportName, closestHitEntry, anyHitEntry, localBindingLayout);
    }

    // Procedural primitive hit group, for AABB geometries (Donut_AddTriangleBlasAabbGeometry): its
    // intersection shader by entry name, then closest-hit / any-hit shaders as above ("" for none).
    addProceduralHitGroup(shaderLibrary: Opaque, exportName: string, intersectionEntry: string, closestHitEntry: string, anyHitEntry: string, localBindingLayout: Opaque | null): void {
        Donut_RtPipelineAddProceduralHitGroup(this.handle, shaderLibrary, exportName, intersectionEntry, closestHitEntry, anyHitEntry, localBindingLayout);
    }

    // The largest hit attributes the pipeline's shaders pass (ReportHit's attributes; the default is 8
    // bytes, the triangles' barycentrics). D3D12 only: Vulkan takes it from the shaders.
    setMaxAttributeSize(byteSize: int): void {
        Donut_RtPipelineSetMaxAttributeSize(this.handle, byteSize);
    }

    // Whether the pipeline's rays see the opacity micromaps of the BLASes they trace (off by default).
    setAllowOpacityMicromaps(allow: int): void {
        Donut_RtPipelineSetAllowOpacityMicromaps(this.handle, allow);
    }
}

export class GraphicsPipelineDesc {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    // Graphics pipelines of any shape: a description built with the Donut_GraphicsPipeline* functions,
    // freed by Donut_CreateGraphicsPipelineFromDesc. It starts as a triangle list with NVRHI's default
    // render state: depth test (less) and writes, back faces culled (clockwise triangles are front
    // faces), solid fill, no blending.
    static create(vertexShader: Opaque, pixelShader: Opaque): GraphicsPipelineDesc {
        return new GraphicsPipelineDesc(Donut_CreateGraphicsPipelineDesc(vertexShader, pixelShader));
    }

    // Same, for a meshlet pipeline (Donut_CreateMeshletPipelineFromDesc): amplification (null for none),
    // mesh and pixel shaders, the rest set with the same functions. Its primitive type is what the mesh
    // shader outputs (its outputtopology).
    static createMeshlet(amplificationShader: Opaque | null, meshShader: Opaque, pixelShader: Opaque): GraphicsPipelineDesc {
        return new GraphicsPipelineDesc(Donut_CreateMeshletPipelineDesc(amplificationShader, meshShader, pixelShader));
    }

    addBindingLayout(bindingLayout: Opaque): void {
        Donut_GraphicsPipelineAddBindingLayout(this.handle, bindingLayout);
    }

    setInputLayout(inputLayout: Opaque): void {
        Donut_GraphicsPipelineSetInputLayout(this.handle, inputLayout);
    }

    setPrimitiveType(primitiveType: PrimitiveType): void {
        Donut_GraphicsPipelineSetPrimitiveType(this.handle, primitiveType);
    }

    // A geometry shader between the vertex (or domain) shader and the rasterizer.
    setGeometryShader(geometryShader: Opaque): void {
        Donut_GraphicsPipelineSetGeometryShader(this.handle, geometryShader);
    }

    // Hull and domain shaders, drawing patches of controlPoints vertices.
    setTessellation(hullShader: Opaque, domainShader: Opaque, controlPoints: int): void {
        Donut_GraphicsPipelineSetTessellation(this.handle, hullShader, domainShader, controlPoints);
    }

    setDepthState(testEnable: int, writeEnable: int, depthFunc: ComparisonFunc): void {
        Donut_GraphicsPipelineSetDepthState(this.handle, testEnable, writeEnable, depthFunc);
    }

    // The depth bounds test: pixels whose depth target value is outside the draw's bounds
    // (Donut_DrawSetDepthBounds) are discarded (requires Donut_HasDepthBoundsTest).
    setDepthBoundsTest(enable: int): void {
        Donut_GraphicsPipelineSetDepthBoundsTest(this.handle, enable);
    }

    setRasterState(cullMode: CullMode, fillMode: FillMode, frontCounterClockwise: int): void {
        Donut_GraphicsPipelineSetRasterState(this.handle, cullMode, fillMode, frontCounterClockwise);
    }

    // Primitives clipped at the near and far planes (as Vulkan by default), or not (the default here:
    // on D3D what lies beyond them is drawn, its depth clamped).
    setDepthClip(enable: int): void {
        Donut_GraphicsPipelineSetDepthClip(this.handle, enable);
    }

    // depthBias units of the depth format's resolution plus slopeScaledDepthBias times the depth
    // slope, clamped to depthBiasClamp in magnitude (0: no clamp).
    setDepthBias(depthBias: int, depthBiasClamp: number, slopeScaledDepthBias: number): void {
        Donut_GraphicsPipelineSetDepthBias(this.handle, depthBias, depthBiasClamp, slopeScaledDepthBias);
    }

    // Blending of every color target.
    setBlendMode(blendMode: BlendMode): void {
        Donut_GraphicsPipelineSetBlendMode(this.handle, blendMode);
    }

    // Blending of every color target, on or off, by the blend factors and operations of the color and
    // of the alpha; the color write mask stays.
    setBlendState(enable: int, srcBlend: BlendFactor, destBlend: BlendFactor, blendOp: BlendOp, srcBlendAlpha: BlendFactor, destBlendAlpha: BlendFactor, blendOpAlpha: BlendOp): void {
        Donut_GraphicsPipelineSetBlendState(this.handle, enable, srcBlend, destBlend, blendOp, srcBlendAlpha, destBlendAlpha, blendOpAlpha);
    }

    // An advanced blend operation for the targets that blend, instead of their factors and operations
    // (Vulkan, with Donut_GetAdvancedBlendOperations): its number from VK_BLEND_OP_ZERO_EXT (0 Zero ...
    // 45 Blue, -1 for none), whether the source and destination colors are premultiplied by their
    // alpha, and how they overlap (0 uncorrelated, 1 disjoint, 2 conjoint).
    setAdvancedBlendOp(advancedBlendOp: int, srcPremultiplied: int, dstPremultiplied: int, overlap: int): void {
        Donut_GraphicsPipelineSetAdvancedBlendOp(this.handle, advancedBlendOp, srcPremultiplied, dstPremultiplied, overlap);
    }

    // A logic operation between the pixel shader's output and the targets' bits instead of blending
    // (requires Donut_HasLogicOps; UINT and UNORM targets).
    setLogicOp(enable: int, logicOp: LogicOp): void {
        Donut_GraphicsPipelineSetLogicOp(this.handle, enable, logicOp);
    }

    // Conservative rasterization (requires Feature.ConservativeRasterization): every pixel a triangle
    // touches is drawn; extraOverestimation enlarges triangles further, in pixels, on Vulkan only
    // (clamped to the device's maximum).
    setConservativeRaster(enable: int, extraOverestimation: number): void {
        Donut_GraphicsPipelineSetConservativeRaster(this.handle, enable, extraOverestimation);
    }

    // Primitive restart: strips restart at the largest index of indexFormat (R16_UINT: 0xFFFF, R32_UINT:
    // 0xFFFFFFFF; UNKNOWN for none), the format of the index buffers the pipeline draws with (D3D12
    // needs it; D3D11 always restarts strips).
    setPrimitiveRestart(indexFormat: Format): void {
        Donut_GraphicsPipelineSetPrimitiveRestart(this.handle, indexFormat);
    }

    // How lines are drawn: their rasterization mode (one Donut_GetLineRasterizationModes has), width (up to
    // Donut_GetMaxLineWidth) and stipple (stippleEnable non-zero, with the mode's stippled bit: each bit
    // of the 16-bit pattern, from the lowest, a run of stippleFactor pixels drawn if set). D3D has no
    // width or stipple.
    setLineRasterization(mode: LineRasterizationMode, width: number, stippleEnable: int, stippleFactor: int, stipplePattern: int): void {
        Donut_GraphicsPipelineSetLineRasterization(this.handle, mode, width, stippleEnable, stippleFactor, stipplePattern);
    }

    // The channels every color target writes (ColorMask bits; None for a pass that only writes UAVs).
    setColorWriteMask(mask: ColorMask): void {
        Donut_GraphicsPipelineSetColorWriteMask(this.handle, mask);
    }

    // The channels one render target (SV_Target<target>) is written in (0 writes nothing to it).
    setTargetColorWriteMask(target: int, mask: ColorMask): void {
        Donut_GraphicsPipelineSetTargetColorWriteMask(this.handle, target, mask);
    }

    // Variable rate shading in a pipeline: its draws take the draw state's shading rate
    // (Donut_DrawSetVariableRateShading) combined with the framebuffer's shading rate surface.
    setVariableRateShading(enabled: int): void {
        Donut_GraphicsPipelineSetVariableRateShading(this.handle, enabled);
    }
}

